private getThinkingBorderColor(level: ThinkingLevel): (str: string) => string {
	// More thinking = more color (muted → dim → border → accent)
	switch (level) {
		case "off":
			return (str: string) => theme.fg("muted", str);
		case "minimal":
			return (str: string) => theme.fg("dim", str);
		case "low":
			return (str: string) => theme.fg("border", str);
		case "medium":
			return (str: string) => theme.fg("borderAccent", str);
		case "high":
			return (str: string) => theme.fg("accent", str);
		default:
			return (str: string) => theme.fg("muted", str);
	}
}

